ma_crossover.content:
// Moving Average Crossover - Pine Script v5
//@version=5
strategy("MA Crossover", overlay=true)

// MA Parameters
fastLen = input(20, title="Fast MA Length")
slowLen = input(50, title="Slow MA Length")

// Calculate MAs
fastMA = ta.sma(close, fastLen)
slowMA = ta.sma(close, slowLen)

// Signals
bullish = ta.crossover(fastMA, slowMA)
bearish = ta.crossunder(fastMA, slowMA)

// Execute
if bullish
    strategy.entry("Long", strategy.long)
if bearish
    strategy.entry("Short", strategy.short)

// Plot
plot(fastMA, color=color.blue, title="Fast MA")
plot(slowMA, color=color.orange, title="Slow MA")

rsi_strategy.content:
// Sample RSI Strategy - Pine Script v5
//@version=5
strategy("RSI Strategy Sample", overlay=false)

// RSI Parameters
rsiLength = input(14, title="RSI Length")
oversoldLevel = input(30, title="Oversold Level")
overboughtLevel = input(70, title="Overbought Level")

// Calculate RSI
rsi = ta.rsi(close, rsiLength)

// Trading Logic
longSignal = rsi < oversoldLevel
shortSignal = rsi > overboughtLevel

// Execute Orders
if longSignal
    strategy.entry("Long", strategy.long)
if shortSignal
    strategy.entry("Short", strategy.short)

// Plot
plot(rsi, title="RSI", color=color.blue)
hline(oversoldLevel, color=color.red, linestyle=hline.style_dashed)
hline(overboughtLevel, color=color.red, linestyle=hline.style_dashed)
hline(50, color=color.gray, linestyle=hline.style_dotted)

volatility.content:
// Volatility Indicator - Pine Script v5
@version = 5
strategy("Volatility", overlay=false)

// Volatility Parameters
period = input(20, title="Period")

// Calculate ATR (Average True Range)
atr = ta.atr(period)

// Calculate volatility as percentage
volatility = (atr / close) * 100

// Thresholds
highVolThreshold = input(2.0, title="High Volatility")
lowVolThreshold = input(0.5, title="Low Volatility")

// Signals
highVol = volatility > highVolThreshold
lowVol = volatility < lowVolThreshold
highVolSignal = ta.crossover(volatility, highVolThreshold)
lowVolSignal = ta.crossunder(volatility, lowVolThreshold)

// Execute (signal-based)
if highVolSignal
    strategy.entry("Vol High", strategy.long)
if lowVolSignal
    strategy.entry("Vol Low", strategy.short)

// Plot
plot(volatility, title="Volatility %", color=color.purple)
hline(highVolThreshold, color=color.red, linestyle=hline.style_dashed)
hline(lowVolThreshold, color=color.green, linestyle=hline.style_dashed)
plotshape(highVolSignal, title="High Vol Signal", style=shape.triangleup, location=location.bottom, color=color.red, size=size.tiny, text="HV")
plotshape(lowVolSignal, title="Low Vol Signal", style=shape.triangledown, location=location.top, color=color.green, size=size.tiny, text="LV")

alertcondition(highVolSignal, title="High Volatility Signal", message="High volatility threshold crossed")
alertcondition(lowVolSignal, title="Low Volatility Signal", message="Low volatility threshold crossed")
